import{_ as o,a0 as s,w as u,s as m,ao as l,I as r,a1 as n,A as e,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器 | LCTT x X-CMD","titleTemplate":false,"description":"Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160724  Terminator A Linux Terminal Emulator With Multiple Terminals In One Window","title":"Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器","tag":"201610","desc":""},"relativePath":"201610/20160724  Terminator A Linux Terminal Emulator With Multiple Terminals In One Window.md","filePath":"[post].md"}'),p={name:"201610/20160724  Terminator A Linux Terminal Emulator With Multiple Terminals In One Window.md"};function d(h,t,T,x,g,b){const a=s("Link");return u(),m("div",null,[t[17]||(t[17]=l('<h1 id="terminator-一款一個窗口包含多個終端的-linux-終端仿真器" tabindex="-1">Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器 <a class="header-anchor" href="#terminator-一款一個窗口包含多個終端的-linux-終端仿真器" aria-label="Permalink to “Terminator：一款一個窗口包含多個終端的 Linux 終端仿真器”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/lots-of-terminals-in-terminator_1.jpg?659" alt=""></p><p>為了通過命令列和系統互動，每一款 Linux 發行版都有一款默認的終端仿真器。但是，默認的終端應用可能不適合你。為了大幅提升你工作的速度，有好多款終端應用提供了更多的功能，可以同時執行更多的任務。這些有用的終端仿真器就包括 Terminator，這是一款 Linux 系統下支持多窗口的自由開源的終端仿真器。</p><h3 id="什麼是-linux-終端仿真器" tabindex="-1">什麼是 Linux 終端仿真器 <a class="header-anchor" href="#什麼是-linux-終端仿真器" aria-label="Permalink to “什麼是 Linux 終端仿真器”">​</a></h3><p>Linux 終端仿真器是一個讓你和 shell 交互的程序。所有的 Linux 發行版都會自帶一款 Linux 終端應用讓你向 shell 傳遞命令。</p><h3 id="terminator-一款自由開源的-linux-終端應用" tabindex="-1">Terminator，一款自由開源的 Linux 終端應用 <a class="header-anchor" href="#terminator-一款自由開源的-linux-終端應用" aria-label="Permalink to “Terminator，一款自由開源的 Linux 終端應用”">​</a></h3><p>Terminator 是一款 Linux 終端模擬器，提供了你的默認的終端應用不支持的多個特性。它提供了在一個窗口創建多個終端的功能，以加快你的工作速度。除了多窗口外，它也允許你修改其它特性，例如字體、字體顏色、背景色等等。讓我們看看我們如何安裝它，並且如何在不同的 Linux 發行版下使用 Terminator。</p><h3 id="如何在-linux-下安裝-terminator" tabindex="-1">如何在 Linux 下安裝 Terminator？ <a class="header-anchor" href="#如何在-linux-下安裝-terminator" aria-label="Permalink to “如何在 Linux 下安裝 Terminator？”">​</a></h3><h4 id="在基於-ubuntu-的發行版上安裝-terminator" tabindex="-1">在基於 Ubuntu 的發行版上安裝 Terminator <a class="header-anchor" href="#在基於-ubuntu-的發行版上安裝-terminator" aria-label="Permalink to “在基於 Ubuntu 的發行版上安裝 Terminator”">​</a></h4><p>Terminator 在默認的 Ubuntu 倉庫就可以使用。所以你不需要添加額外的 PPA。只需要使用 APT 或者“軟件應用”在 Ubuntu 下直接安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install terminator</span></span></code></pre></div><p>假如你的默認的倉庫中 Terminator 不可用，只需要使用源碼編譯 Terminator 即可。</p>',12)),r("ul",null,[r("li",null,[n(a,{href:"https://launchpad.net/terminator/+download"},{default:e(()=>[...t[0]||(t[0]=[i("下載源碼",-1)])]),_:1})])]),t[18]||(t[18]=l('<p>下載 Terminator 源碼並且解壓到你的桌面。現在打開你的默認的終端，然後 <code>cd</code> 到解壓的目錄。</p><p>現在就可以使用下面的命令來安裝 Terminator 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ./setup.py install</span></span></code></pre></div><h4 id="在-fedora-及衍生的操作系統上安裝-terminator" tabindex="-1">在 Fedora 及衍生的操作系統上安裝 Terminator <a class="header-anchor" href="#在-fedora-及衍生的操作系統上安裝-terminator" aria-label="Permalink to “在 Fedora 及衍生的操作系統上安裝 Terminator”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf install terminator</span></span></code></pre></div><h4 id="在-opensuse-上安裝-terminator" tabindex="-1">在 OpenSuse 上安裝 Terminator <a class="header-anchor" href="#在-opensuse-上安裝-terminator" aria-label="Permalink to “在 OpenSuse 上安裝 Terminator”">​</a></h4>',6)),r("p",null,[t[2]||(t[2]=i("參見此文：",-1)),n(a,{href:"http://software.opensuse.org/download.html?project=home%3AKorbi123&package=terminator"},{default:e(()=>[...t[1]||(t[1]=[i("在 OPENSUSE 上安裝",-1)])]),_:1}),t[3]||(t[3]=i("。",-1))]),t[19]||(t[19]=l('<h3 id="如何在一個窗口使用多個終端" tabindex="-1">如何在一個窗口使用多個終端？ <a class="header-anchor" href="#如何在一個窗口使用多個終端" aria-label="Permalink to “如何在一個窗口使用多個終端？”">​</a></h3><p>安裝好 Terminator 之後，你可以簡單的在一個窗口打開多個終端。只需要右鍵點擊並切分。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/multiple-terminals-in-terminator_orig.jpg" alt=""></p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/multiple-terminals-in-terminator-emulator.jpg?697" alt=""></p><p>只要你願意，你可以創建儘可能多的終端，只要你能管理得過來。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/lots-of-terminals-in-terminator.jpg?706" alt=""></p><h3 id="定製終端" tabindex="-1">定製終端 <a class="header-anchor" href="#定製終端" aria-label="Permalink to “定製終端”">​</a></h3><p>右鍵點擊終端，並單擊屬性。現在你可以定製字體、字體顏色、標題顏色和背景，還有終端字體顏色和背景。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/customize-terminator-interface.jpg?702" alt=""></p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/free-terminal-emulator_orig.jpg" alt=""></p><h3 id="結論-什麼是你最喜歡的終端模擬器" tabindex="-1">結論：什麼是你最喜歡的終端模擬器 <a class="header-anchor" href="#結論-什麼是你最喜歡的終端模擬器" aria-label="Permalink to “結論：什麼是你最喜歡的終端模擬器”">​</a></h3><p>Terminator 是一款先進的終端模擬器，它可以讓你自定義界面。如果你還沒有從你默認的終端模擬器中切換過來的話，你可以嘗試一下它。我知道你將會喜歡上它。如果你正在使用其他的自由開源的終端模擬器的話，請讓我們知道你最喜歡的那一款。不要忘了和你的朋友分享這篇文章。或許你的朋友正在尋找類似的東西。</p><hr>',13)),r("p",null,[t[5]||(t[5]=i("via: ",-1)),n(a,{href:"http://www.linuxandubuntu.com/home/terminator-a-linux-terminal-emulator-with-multiple-terminals-in-one-window"},{default:e(()=>[...t[4]||(t[4]=[i("http://www.linuxandubuntu.com/home/terminator-a-linux-terminal-emulator-with-multiple-terminals-in-one-window",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=i("作者：",-1)),n(a,{href:"http://www.linuxandubuntu.com/home/terminator-a-linux-terminal-emulator-with-multiple-terminals-in-one-window"},{default:e(()=>[...t[6]||(t[6]=[i("author",-1)])]),_:1}),t[10]||(t[10]=i(" 譯者：",-1)),n(a,{href:"https://github.com/yangmingming"},{default:e(()=>[...t[7]||(t[7]=[i("yangmingming",-1)])]),_:1}),t[11]||(t[11]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[12]||(t[12]=[i("LCTT",-1)])]),_:1}),t[15]||(t[15]=i(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:e(()=>[...t[13]||(t[13]=[i("Linux中國",-1)])]),_:1}),t[16]||(t[16]=i(" 榮譽推出",-1))])])}const L=o(p,[["render",d]]);export{k as __pageData,L as default};
